class Solution {
    public int minimumRounds(int[] tasks){
        Map<Integer,Integer> count=new HashMap<>();
        for(int task:tasks)count.merge(task,1,Integer::sum);
        int answer=0;
        for(int value:count.values()){
            if(value==1)return -1;
            answer+=(value+2)/3;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minimumRounds(tasks:IntArray):Int{
        val count=tasks.toList().groupingBy{
            it
        }.eachCount();
        var answer=0;
        for(value in count.values){
            if(value==1)return -1;
            answer+=(value+2)/3
        };
        return answer
    }
}

code.cpp:
class Solution {
    public:int minimumRounds(vector<int>& tasks){
        unordered_map<int,int> count;
        for(int task:tasks)++count[task];
        int answer=0;
        for(auto [_,value]:count){
            if(value==1)return -1;
            answer+=(value+2)/3;
        }
        return answer;
    }
};
